/// 🧾️ Resident page allocation retains the original receipt and callback state across turns.
struct PagedTextEncodeReservation{grant:RetainedCloneGrant,limit:Option<usize>,bytes:usize,quote:(usize,usize,u64),local:RetainedCloneProgress,state:crate::native_encoding::NativeEncodeEffectState,failure:Option<crate::native_encoding::NativeEncodeEffectFailure>}
